"""Create a temporary local-only iframe host for actual CSS viewport QA.

Never commit or publish public/lunar-responsive-qa.html. A normal Jekyll build
removes it. Frame widths are verified from the child document, not inferred
from the desktop app's screenshot scale.
"""
import json
from pathlib import Path
from core import ROOT

routes=['/menulio-kalendorius/','/menulio-fazes/']+['/'+str(p.parent.relative_to(ROOT/'site'))+'/' for p in sorted((ROOT/'site/menulio-kalendorius').rglob('index.html')) if p.parent!=ROOT/'site/menulio-kalendorius']
template='''<!doctype html><html lang="lt"><meta charset="utf-8"><title>Vietinė adaptyvumo patikra</title><style>html,body{margin:0;background:#e4eaed;font:14px Arial}header{height:38px;padding:8px;box-sizing:border-box}iframe{display:block;border:0;background:white;margin:0 8px}</style><header>Vietinė patikra · <span id="size"></span></header><iframe title="Tikrinamas Mėnulio kalendorius"></iframe><script>const routes=ROUTES;const q=new URLSearchParams(location.search);const width=Number(q.get('width'));const path=q.get('path');if([360,390,430,768,1280,1440,1920].includes(width)&&routes.includes(path)){const f=document.querySelector('iframe');f.style.width=width+'px';f.style.height='1000px';f.src=path;document.getElementById('size').textContent=width+' px · '+path;}</script></html>'''
template=template.replace('</script></html>', '''f.addEventListener('load',async()=>{const d=f.contentDocument;if(q.get('print')==='1')f.contentWindow.print=()=>{const o=document.createElement('pre');o.id='print-result';o.textContent=JSON.stringify({image:d.querySelector('.lunar-print-output img').getAttribute('src'),width:d.querySelector('.lunar-print-output img').naturalWidth,height:d.querySelector('.lunar-print-output img').naturalHeight,style:[...d.querySelectorAll('style')].map(s=>s.textContent).find(s=>s.includes('@page{size:'))});document.body.append(o);};const ready=document.createElement('pre');ready.id='images-ready';ready.dataset.state='running';document.body.append(ready);await d.fonts.ready;const images=[...d.querySelectorAll('.lunar-app img[src]:not([loading=lazy])')];await Promise.all(images.map(i=>i.decode().catch(()=>{})));await new Promise(resolve=>f.contentWindow.requestAnimationFrame(()=>f.contentWindow.requestAnimationFrame(resolve)));ready.textContent=JSON.stringify({broken:images.filter(i=>!i.complete||i.naturalWidth===0).map(i=>i.getAttribute('src')),count:images.length});ready.dataset.state='done';if(q.get('font')==='200')d.documentElement.style.fontSize='200%';if(q.get('axe')==='1'){const output=document.createElement('pre');output.id='a11y-results';output.dataset.state='running';document.body.append(output);const s=d.createElement('script');s.src='/lunar-qa-axe.js';s.onload=async()=>{try{const r=await f.contentWindow.axe.run(d,{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21aa','wcag22aa']}});output.textContent=JSON.stringify({violations:r.violations.map(v=>({id:v.id,impact:v.impact,description:v.description,nodes:v.nodes.map(n=>({target:n.target,summary:n.failureSummary}))})),incomplete:r.incomplete.map(v=>({id:v.id,nodes:v.nodes.map(n=>({target:n.target,summary:n.failureSummary,checks:n.any.map(c=>c.message)}))})),passes:r.passes.length});output.dataset.state='done';}catch(error){output.textContent=String(error);output.dataset.state='failed';}};d.head.append(s);}});</script></html>''')
# The hook needs the same frame reference after the width/path validation.
template=template.replace("const width=Number(q.get('width'));const path=q.get('path');", "const width=Number(q.get('width'));const path=q.get('path');const f=document.querySelector('iframe');")
template=template.replace("{const f=document.querySelector('iframe');f.style.width", "{f.style.width")
(ROOT/'public/lunar-responsive-qa.html').write_text(template.replace('ROUTES',json.dumps(routes)))
(ROOT/'docs/lunar/qa/browser-targets.json').write_text(json.dumps(routes,indent=2)+'\n')
print(f'Local harness ready for {len(routes)} routes; remove with the final production build.')
